{"content":"package ledger

import (
    "context"
    "errors"
    "sync"
    "testing"
)

func TestTransferOne(t *testing.T) {
    book := NewLedger(map[string]int64{"a": 10, "b": 0})
    got, err := book.Transfer(context.Background(), "tx-1", "a", "b", 3)
    if err != nil || got.FromBalance != 7 || got.ToBalance != 3 { t.Fatalf("receipt=%+v error=%v", got, err) }
}

func TestTransferValidation(t *testing.T) {
    book := NewLedger(map[string]int64{"a": 10, "b": 5})
    if _, err := book.Transfer(context.Background(), "", "a", "b", 1); !errors.Is(err, ErrInvalid) {
        t.Fatalf("empty id: %v", err)
    }
    if _, err := book.Transfer(context.Background(), "x", "a", "a", 1); !errors.Is(err, ErrInvalid) {
        t.Fatalf("same account: %v", err)
    }
    if _, err := book.Transfer(context.Background(), "x", "a", "missing", 1); !errors.Is(err, ErrMissingAccount) {
        t.Fatalf("missing to: %v", err)
    }
    if _, err := book.Transfer(context.Background(), "x", "missing", "b", 1); !errors.Is(err, ErrMissingAccount) {
        t.Fatalf("missing from: %v", err)
    }
    if _, err := book.Transfer(context.Background(), "x", "a", "b", 0); !errors.Is(err, ErrInvalid) {
        t.Fatalf("zero amount: %v", err)
    }
    if _, err := book.Transfer(context.Background(), "x", "a", "b", -1); !errors.Is(err, ErrInvalid) {
        t.Fatalf("negative amount: %v", err)
    }
}

func TestTransferInsufficientFunds(t *testing.T) {
    book := NewLedger(map[string]int64{"a": 5, "b": 0})
    if _, err := book.Transfer(context.Background(), "tx", "a", "b", 6); !errors.Is(err, ErrInsufficientFunds) {
        t.Fatalf("err=%v", err)
    }
    if bal, _ := book.Balance("a"); bal != 5 { t.Fatalf("a=%d", bal) }
    if bal, _ := book.Balance("b"); bal != 0 { t.Fatalf("b=%d", bal) }
}

func TestTransferIdempotentRetry(t *testing.T) {
    book := NewLedger(map[string]int64{"a": 10, "b": 0})
    first, err := book.Transfer(context.Background(), "tx", "a", "b", 4)
    if err != nil { t.Fatal(err) }
    second, err := book.Transfer(context.Background(), "tx", "a", "b", 4)
    if err != nil { t.Fatal(err) }
    if second != first { t.Fatalf("second=%+v first=%+v", second, first) }
    if bal, _ := book.Balance("a"); bal != 6 { t.Fatalf("a=%d", bal) }
    if bal, _ := book.Balance("b"); bal != 4 { t.Fatalf("b=%d", bal) }
}

func TestTransferConflict(t *testing.T) {
    book := NewLedger(map[string]int64{"a": 10, "b": 0, "c": 0})
    if _, err := book.Transfer(context.Background(), "tx", "a", "b", 4); err != nil { t.Fatal(err) }
    if _, err := book.Transfer(context.Background(), "tx", "a", "c", 4); !errors.Is(err, ErrConflict) {
        t.Fatalf("err=%v", err)
    }
    if _, err := book.Transfer(context.Background(), "tx", "a", "b", 5); !errors.Is(err, ErrConflict) {
        t.Fatalf("err=%v", err)
    }
}

func TestTransferCancelledContext(t *testing.T) {
    book := NewLedger(map[string]int64{"a": 10, "b": 0})
    ctx, cancel := context.WithCancel(context.Background())
    cancel()
    if _, err := book.Transfer(ctx, "tx", "a", "b", 4); err == nil {
        t.Fatal("expected error")
    }
    if bal, _ := book.Balance("a"); bal != 10 { t.Fatalf("a=%d", bal) }
    if bal, _ := book.Balance("b"); bal != 0 { t.Fatalf("b=%d", bal) }
}

func TestTransferConcurrent(t *testing.T) {
    book := NewLedger(map[string]int64{"a": 1000, "b": 0})
    var wg sync.WaitGroup
    for i := 0; i < 50; i++ {
        wg.Add(1)
        go func(i int) {
            defer wg.Done()
            id := "tx-" + string(rune('a'+i%26)) + "-" + string(rune('0'+i/26))
            _, _ = book.Transfer(context.Background(), id, "a", "b", 1)
        }(i)
    }
    wg.Wait()
    a, _ := book.Balance("a")
    b, _ := book.Balance("b")
    if a+b != 1000 { t.Fatalf("total=%d", a+b) }
    if b != 50 { t.Fatalf("b=%d", b) }
}

func TestTransferConcurrentSameID(t *testing.T) {
    book := NewLedger(map[string]int64{"a": 100, "b": 0})
    var wg sync.WaitGroup
    receipts := make([]Receipt, 20)
    for i := 0; i < 20; i++ {
        wg.Add(1)
        go func(i int) {
            defer wg.Done()
            r, err := book.Transfer(context.Background(), "same", "a", "b", 5)
            if err != nil { t.Error(err); return }
            receipts[i] = r
        }(i)
    }
    wg.Wait()
    for i := 1; i < 20; i++ {
        if receipts[i] != receipts[0] { t.Fatalf("receipts differ: %+v vs %+v", receipts[i], receipts[0]) }
    }
    if bal, _ := book.Balance("a"); bal != 95 { t.Fatalf("a=%d", bal) }
    if bal, _ := book.Balance("b"); bal != 5 { t.Fatalf("b=%d", bal) }
}
